    if (code.includes("!")) return;
    const shown = w.replace(" _ ", yes ? " — " : " ");
    dashItems.push(yes ? ["wt", shown, DASH_YES.indexOf(k)] : ["wn", shown, DASH_NO.indexOf(k)]);
